-- Frequents data (hypothetically violating PK for demonstration):
-- If Frequents had an 'id' PK, these would be valid:
-- INSERT INTO Frequents (id, drinker, bar, times_a_week) VALUES (1, 'Alice', 'The Tap', 3);
-- INSERT INTO Frequents (id, drinker, bar, times_a_week) VALUES (2, 'Alice', 'The Tap', 4);
